def p(t,style="AppBody"): return Paragraph(t,styles[style])
def table(rows,widths):
    data=[]
    for i,row in enumerate(rows): data.append([p(str(c),"AppSmallBold" if i==0 else "AppSmall") for c in row])
    t=Table(data,colWidths=widths,repeatRows=1,hAlign="CENTER")
    t.setStyle(TableStyle([("GRID",(0,0),(-1,-1),.4,colors.HexColor("#666666")),("BACKGROUND",(0,0),(-1,0),colors.HexColor("#E7E7E7")),("VALIGN",(0,0),(-1,-1),"TOP"),("LEFTPADDING",(0,0),(-1,-1),5),("RIGHTPADDING",(0,0),(-1,-1),5),("TOPPADDING",(0,0),(-1,-1),5),("BOTTOMPADDING",(0,0),(-1,-1),5)]))
    return t

def bullets(items):
    return ListFlowable([ListItem(p(x),leftIndent=8) for x in items],bulletType="bullet",leftIndent=18,bulletFontName="Times-Roman",bulletFontSize=7,spaceAfter=5)

entries=[]
def add(title, intro, points, review, table_rows=None):
    entries.append({"title":title,"intro":intro,"points":points,"review":review,"table":table_rows})

# Appendix A - source and architecture walkthrough (10 pages)
add("A.1 Repository map and system boundary", "The supplied project is divided into three executable areas: a Vite and React web interface, a Spring Boot service, and a Chrome extension content script. The README describes the intended end-to-end feature, but its illustrative folder names do not exactly match the current repository. For this report, the checked-in files are treated as the source of truth when code behavior differs from prose documentation.", ["email-writer-react/src/App.jsx contains the visible form, asynchronous request, loading state, output panel, and copy action.","EmailWriter-backend/src/main/java contains the request DTO, REST controller, application class, and Gemini service.","EmailWriterExtension/manifest.json and content.js describe the Gmail page integration; no bundled React extension popup is present in the manifest."], "Keep the web app and extension diagrams as separate client paths that converge on one backend endpoint. Do not describe absent account, billing, storage, or mailbox-send functionality as implemented.")
add("A.2 React entry point and component responsibilities", "The React entry point imports the global stylesheet and renders App inside StrictMode. The App component is a single-page interaction surface rather than a multi-route product. Its controls are composed from Material UI, while Axios is used for the HTTP request. This arrangement makes the prototype easy to inspect, but it places most presentation, input handling, request orchestration, and output logic in one component.", ["main.jsx creates the React root using the #root element from index.html.","App.jsx owns five state values: source text, selected tone, generated text, loading status, and user-facing error.","The supplied package uses React 19, Material UI 7, Axios 1, and Vite 7; these versions are read from the project manifest."], "A future refactor could extract a reply form, tone selector, output panel, and request hook. Such a refactor should preserve the currently visible behavior and should be documented as future work unless completed.")
add("A.3 Input state and tone selection", "The original message is held in component state and displayed in a multiline text field. The tone control offers an empty option plus Professional, Casual, and Friendly. The user may submit with no explicit tone. The project has no server-side allow-list, so the request DTO currently accepts whatever string a client supplies. The extension sends a fixed tone value rather than presenting this selector.", ["The web interface trims input only for its blank check; it sends the original entered text in the JSON payload.","Changing the tone updates the React state and is included in the next request.","The extension's fixed professional setting means the available tone behavior is not consistent across the two clients."], "A clear contract should define accepted tone identifiers, their exact wording, and the behavior for missing or unrecognized values. Server validation should be authoritative even when the UI constrains its options.")
add("A.4 Submission state and request lifecycle", "When Generate Reply is activated, the interface clears a previous error and sets loading to true. Axios posts emailContent and tone to the local API route. While awaiting the response, the button is disabled and a progress indicator is rendered. A successful response is assigned to generatedReply. A rejected request triggers a generic failure message. A finally block restores the loading state regardless of success or failure.", ["The source prevents a whitespace-only request from reaching the API through the web form.","The user sees a spinner but no cancellation action or request timeout configuration in App.jsx.","The catch block discards diagnostic details and presents a short retry message."], "Keeping detailed diagnostic output in developer logs while showing safe, useful error categories to the user would improve support. Avoid placing message text or credentials in logs.")
add("A.5 Generated reply display and clipboard action", "A non-empty generatedReply renders a bordered result panel. The reply is shown with line breaks preserved, which helps retain paragraph formatting returned by the model. The Copy to Clipboard button uses navigator.clipboard.writeText. The source does not show a copy confirmation state, fallback for clipboard permission failure, or an edit field separate from the displayed response.", ["The panel distinguishes the generated text with a heading.","Clipboard writing is initiated only after the user activates the copy control.","The application does not submit or send the email on the user's behalf."], "For a production interface, indicate whether copy succeeded, preserve keyboard focus, and let the user edit the proposed text before copying. Keep the final decision to send with the user.")
add("A.6 REST controller and route", "EmailGeneratorController is annotated as a REST controller and uses the base mapping /api/email. Its POST mapping /generate binds a JSON EmailRequest and returns ResponseEntity<String>. The controller delegates the work to emailServices and wraps the returned text in an HTTP 200 response. Cross-origin requests are currently permitted from any origin by the annotation.", ["The public route used by both clients is POST /api/email/generate.","The controller does not currently expose a separate health or readiness endpoint in the inspected source.","There is no controller-level validation or exception-to-status mapping shown."], "Before external deployment, use an explicit origin policy, validate incoming payloads, and return a documented response model with appropriate HTTP status codes for invalid input and upstream failures.", [["Request","Current code behavior","Recommended contract"],["Method and path","POST /api/email/generate","Retain or version intentionally"],["Body","emailContent and tone","Validate type, length, and accepted tone"],["Response","Raw string","Stable JSON response object"]])
add("A.7 Request DTO and application configuration", "EmailRequest uses Lombok's Data annotation to supply accessors for emailContent and tone. The backend configuration names the application EmailWritter and resolves gemini.api.url and gemini.api.key from environment properties. The URL and key are configuration inputs; no literal credential is present in the checked-in application.properties file. A deployment must still provide valid values at runtime.", ["The DTO does not declare explicit validation annotations in the supplied file.","The project uses Java 17 in the Maven properties.","The property placeholders use GEMINI_URL and GEMINI_KEY, so local setup instructions need to explain both values without publishing secrets."], "Keep local secrets outside version control, fail startup clearly when required configuration is absent, and separate local development settings from production deployment settings.")
add("A.8 Prompt construction", "The service constructs an instruction asking for a professional email reply and no subject line. If a non-empty tone is supplied, a second instruction asks Gemini to use that tone. The original email is appended after an Original Email label. This prompt is concise and demonstrates context passing, but the default professional instruction can conflict with a Casual or Friendly selection.", ["The prompt includes the submitted email body as model input.","The source does not currently label the incoming email as untrusted content or instruct the model to ignore instructions embedded within it.","The prompt does not explicitly constrain length, factual invention, or use of placeholders for missing facts."], "Prompt changes should be reviewed with test cases for each supported tone and adversarial email content. The generated result should remain an untrusted draft that the user checks before use.")
add("A.9 External request and response extraction", "WebClient sends a JSON payload with a contents array, parts array, and a text field containing the constructed prompt. The response is read as a string and parsed with Jackson. The service selects the first candidate and first text part. Parsing exceptions are caught and returned as an error string. Transport exceptions and non-success HTTP responses are not normalized into a typed error model in the supplied implementation.", ["The API key is currently appended to the configured URL as a query parameter.","The parser assumes at least one candidate and one part with text.","The service blocks on the reactive publisher using block(), so the request thread waits for the provider response."], "Add timeout and retry policy only after considering duplicate-generation costs. Handle missing candidate data, refusal responses, quota failures, and network errors with explicit outcomes.")
add("A.10 Chrome extension manifest and content script", "The extension declares Manifest V3, activeTab and storage permissions, localhost and Gmail host access, and a content script matched to mail.google.com. The script observes the page for compose-related mutations, searches for a toolbar, creates a button, reads visible message content, calls the local API, and inserts returned text into an editable compose area. It uses Gmail's DOM directly, not a supported Gmail API workflow.", ["The action manifest provides a title but does not declare a popup page.","The content script includes fallback CSS selectors, but two helper loops return on their first iteration when the first selector misses.","The extension sends the fixed tone string professional and uses the same localhost endpoint as the web UI."], "Test selector behavior with fresh Gmail page structures and multiple open compose windows. The manifest should request only the permissions and origins needed by the release configuration.")

# Appendix B - operations and user guide (8 pages)
add("B.1 Prerequisites and workspace layout", "The README lists Node.js 18 or newer, npm, Java 17 or newer, Maven, and a Google AI project with Gemini API access as prerequisites. The checked-in frontend and backend are in separate directories, and the extension source is in its own folder. A fresh setup should verify runtime versions and install dependencies within the corresponding project before attempting a demonstration.", ["Frontend directory: email-writer-react.","Backend directory: EmailWriter-backend.","Extension source directory: EmailWriterExtension; the supplied manifest is not a built React extension package."], "The commands in the README should be reconciled with the actual repository paths before the report is used as a handover manual. Never commit generated API credentials.")
add("B.2 Configure the Gemini service", "The backend reads the Gemini URL and API key from GEMINI_URL and GEMINI_KEY placeholders. The README gives an example endpoint but the project properties are the runtime source of configuration. A developer should set these values in the local run environment or a protected configuration store. The exact model name and endpoint must match the provider account and current API documentation.", ["Set the URL and credential only in the backend environment.","Do not place the key in React, the extension manifest, content.js, screenshots, or a report appendix.","Confirm that the configured URL is reachable before testing user-visible generation."], "The current service appends the key to the URL. A production update should align with current provider authentication guidance and ensure URLs containing secrets are not retained in logs or monitoring.")
add("B.3 Start the Spring Boot backend", "From the EmailWriter-backend directory, the Maven wrapper can be used to launch the service in a development environment after dependencies and configuration are available. The project's controller is expected to listen on port 8080 according to the README's local setup. Startup should be considered successful only when the process reports that it is listening and the required Gemini properties have been resolved.", ["Windows wrapper: mvnw.cmd spring-boot:run.","Check startup logs for missing placeholders or dependency errors.","Keep the backend terminal open while using either client."], "A production deployment should use a managed runtime, externalized secrets, HTTPS termination, structured health checks, and resource limits. The README currently describes a local demonstration, not a production operations plan.")
add("B.4 Start the React web interface", "The frontend package defines Vite scripts for development, build, lint, and preview. For a local demonstration, install the package dependencies and start the development server from the email-writer-react directory. The current React source sends requests directly to http://localhost:8080, so an API running elsewhere will not be reached without updating the application configuration or client code.", ["Use npm install in the frontend directory when dependencies are not present.","Use npm run dev to open the local Vite interface.","Use npm run build for a static production build; deployment routing and API URL handling still need configuration."], "The endpoint should be configurable by environment or build-time settings rather than hard-coded, and cross-origin policy should match the deployment origin.")
add("B.5 Web interface: prepare the message", "Open the Email Reply Generator page and paste a representative source email into Original Email Content. Use a fictional or approved test message rather than confidential personal or company correspondence. The project sends the entered text to its backend, which forwards it to Gemini. The user should understand this path before entering real email content.", ["Include enough context to make a reply possible, but omit unnecessary personal data.","Do not include passwords, access codes, payment information, or private attachments in a test.","The current form checks that text is not blank before enabling Generate Reply."], "The application does not currently show a data-processing notice or redaction step; those should be included before real-world use.")
add("B.6 Web interface: choose a tone and generate", "Select Professional, Casual, Friendly, or None in the optional tone control, then activate Generate Reply. The button enters a loading state while Axios waits for the API response. When the service succeeds, the returned string appears below the input. The request is synchronous from the user's perspective, and the current UI has no stop or cancel action.", ["Compare the generated wording with the source email and verify names, dates, amounts, commitments, and factual details.","Edit the response before using it whenever the model has omitted context or added unsupported claims.","A tone selection cannot guarantee that every sentence follows the requested style."], "The default prompt's Professional instruction can conflict with other choices. A verified release should harmonize the prompt before claiming all tone options work as expected.")
add("B.7 Use the Chrome extension", "The extension content script is designed to run on Gmail pages, add an AI Reply action to a compose toolbar, obtain visible email text, call the local backend, and insert the response into the draft editor. The manifest grants access to Gmail and the local API. This integration depends on Gmail page markup and must be manually verified in a test mailbox after loading the extension unpacked.", ["The manifest declares Manifest V3 and matches mail.google.com pages.","The current source uses fixed local HTTP and a fixed professional tone.","Review the draft before sending; the extension does not send mail automatically."], "If injection or insertion fails, use the standalone interface or copy workflow where available and record the browser layout and error for debugging.")
add("B.8 Troubleshooting and support notes", "A failed generation can originate in the web interface, the local API, model configuration, provider availability, or browser network policy. The current interface intentionally hides detailed exceptions from the user, so diagnosis should be performed with local developer tools and backend logs while avoiding message text or secrets. The extension also depends on selectors that can stop matching after a Gmail UI change.", ["If the button remains disabled, verify that the input contains non-whitespace characters.","If the request fails, verify backend availability and environment configuration without copying credentials into logs.","If Gmail controls are not found, reload a test page only after confirming no unsaved draft is at risk."], "A support runbook should identify the deployed version, endpoint health, provider status, and client browser version, while minimizing collection of email content.")

