# Appendix K adds full-page technical reference material so each page carries complete project detail.
def add_k_page(title,intro,sections,rows,review):
    story.append(Paragraph(title,styles["AppTitle"]))
    story.append(p(intro))
    for heading,body in sections:
        story.append(Paragraph(heading,styles["AppSub"]))
        story.append(p(body))
    if rows:
        story.append(Spacer(1,3))
        story.append(table(rows,[1.3*inch,2.3*inch,2.4*inch]))
    story.append(Paragraph("Review and interpretation",styles["AppSub"]))
    story.append(p(review))
    story.append(PageBreak())

